<?php declare(strict_types=1);require __DIR__.'/_common.php';$pdo=db();$lang=(($_GET['lang']??'en')==='fr')?'fr':'en';$n=0;$counts=[];if(v2_tables_ready($pdo)){$n=(int)$pdo->query("SELECT COUNT(*) FROM survey_v2_sessions WHERE status IN ('core_submitted','completed')")->fetchColumn();$rows=$pdo->query("SELECT a.question_id,a.answer_json FROM survey_v2_answers a JOIN survey_v2_sessions s ON s.id=a.session_id WHERE s.status IN ('core_submitted','completed')")->fetchAll();foreach($rows as $r){$a=json_decode((string)$r['answer_json'],true);foreach(is_array($a)?$a:[$a] as $x){$counts[$r['question_id']][(string)$x]=($counts[$r['question_id']][(string)$x]??0)+1;}}}$maps=['recent_difficulty'=>['beginning'=>['Beginning','Commencer'],'deciding'=>['Deciding first','Décider quoi faire'],'staying'=>['Staying with it','Rester dessus'],'time'=>['Time','Temps'],'switching'=>['Stopping / switching','S’arrêter / changer'],'returning'=>['Returning','Revenir'],'remembering'=>['Remembering','Se souvenir'],'other'=>['Other','Autre'],'unsure'=>['Unsure','Pas d’exemple']],'today_model'=>['stack'=>['Now + Next','Maintenant + Ensuite'],'clock'=>['Clock-based','Basée sur l’heure'],'checklist'=>['Flexible checklist','Checklist flexible'],'mixed'=>['Fixed + flexible','Fixe + flexible']],'mvp_one'=>['capture'=>['Quick capture','Capture rapide'],'today'=>['Today / next action','Aujourd’hui / prochaine action'],'routines'=>['Routines','Routines'],'chores'=>['Household chores','Tâches ménagères'],'calendar'=>['Calendar','Agenda'],'timer'=>['Focus timer','Timer focus'],'hyperfocus'=>['Hyperfocus','Hyperfocus'],'focus_notes'=>['Quick notes in focus','Notes rapides en focus'],'companion'=>['Companion','Compagnon'],'crafting'=>['Crafting / home','Fabrication / maison'],'stats'=>['Statistics / history','Statistiques / historique'],'reminders'=>['Reminders','Rappels']]];?><!doctype html><html lang="<?=v2_h($lang)?>"><head>
